    s = (s * 1103515245 + 12345) & 0x7fffffff;
    const x = (s / 0x7fffffff) * FIELD.width;
    s = (s * 1103515245 + 12345) & 0x7fffffff;
    const y = (s / 0x7fffffff) * 380;
    s = (s * 1103515245 + 12345) & 0x7fffffff;
